import{b as a,O as e,g as s,j as i}from"./chunks/framework.DcaUmd3X.js";const l="data:image/webp;base64,",n="data:image/webp;base64,",r="data:image/webp;base64,",d="/assets/image-8.DM4Q_OUA.webp",k=JSON.parse('{"title":"变基","description":"","frontmatter":{},"headers":[],"relativePath":"git/branch/rebase/index.md","filePath":"Git操作手册/3.分支管理/04.变基.md","lastUpdated":1783947942000}'),o={name:"git/branch/rebase/index.md"};function p(h,t,c,b,g,u){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="变基" tabindex="-1">变基 <a class="header-anchor" href="#变基" aria-label="Permalink to &quot;变基&quot;">​</a></h1><blockquote><p>git rebase / rebase -i，把分叉的历史捋成一条直线</p></blockquote><h2 id="变基解决什么问题" tabindex="-1">变基解决什么问题 <a class="header-anchor" href="#变基解决什么问题" aria-label="Permalink to &quot;变基解决什么问题&quot;">​</a></h2><p>用 <code>merge</code> 合并分支时，历史会出现分叉：</p><p><img src="'+l+'" alt="alt text"></p><p>功能分支多了之后，提交历史变成一张蜘蛛网。<code>rebase</code> 可以把分叉&quot;捋直&quot;：</p><p><img src="'+n+'" alt="alt text"></p><p>变基的本质：<strong>把 feature 分支的&quot;根&quot;从旧的 master 节点，移到最新的 master 节点上。</strong></p><p>打个比方——变基就像&quot;移植花木&quot;。你把花从旧花盆（老 master）里连根拔起，栽到新花盆（最新 master）里。花还是那束花（代码改动不变），但根基变了（父提交变了）。</p><p>举个例子。假设你昨天从 master 的 C 点拉了一条 feature 分支做登录功能，提交了 X 和 Y。今天同事往 master 合了一个新模块 D：</p><p>变基前（真实历史）：</p><p><img src="'+r+'" alt="alt text"></p><blockquote><p>你和同事并行开发，但 feature &quot;卡&quot;在了老节点 C 上</p></blockquote><p>此时在 feature 分支上执行 <code>git rebase master</code>，Git 做了四件事：</p><ol><li>找到 feature 和 master 的<strong>共同祖先</strong> C</li><li>把 feature 独有的提交 X、Y <strong>暂存</strong>起来</li><li>把 feature 的指针<strong>挪到</strong> master 最新位置 D</li><li>把暂存的 X、Y <strong>逐个重放</strong>到 D 之后 → 得到 X&#39;、Y&#39;</li></ol><p>变基后（重写后的历史）：</p><p><img src="'+d+`" alt="alt text"></p><blockquote><p>feature 现在基于最新的 master，历史变成一条直线，看起来就像你今天刚从 master 开始写登录功能，一气呵成</p></blockquote><h2 id="标准流程-先-rebase-再-merge" tabindex="-1">标准流程：先 rebase，再 merge <a class="header-anchor" href="#标准流程-先-rebase-再-merge" aria-label="Permalink to &quot;标准流程：先 rebase，再 merge&quot;">​</a></h2><p>整套操作分三步，缺一不可：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第一步：切到你的功能分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第二步：把 feature 的提交变基到 master 最新节点之后</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第三步：切回 master，快进合并（不会产生分叉节点）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span></span></code></pre></div><blockquote><p>💡 <code>git rebase master</code> 的意思是&quot;以 master 为基，把当前分支的提交重放到 master 之后&quot;。<strong>你必须在 feature 分支上执行它，不能在 master 上执行。</strong> 在 master 上执行 <code>git rebase master</code> 什么也不会发生。</p></blockquote><p>rebase 做了什么：</p><ol><li>找到 <code>feature</code> 和 <code>master</code> 的共同祖先</li><li>把 <code>feature</code> 上独有的提交暂存</li><li>把 <code>feature</code> 的起点挪到 <code>master</code> 最新位置</li><li>把暂存的提交逐个重新应用</li></ol><p>走完这三步，结果是一条直线的历史——你的所有提交紧跟在 master 最新提交之后，像刚从最新版本开始写的。</p><h2 id="为什么费这么大劲整理历史" tabindex="-1">为什么费这么大劲整理历史 <a class="header-anchor" href="#为什么费这么大劲整理历史" aria-label="Permalink to &quot;为什么费这么大劲整理历史&quot;">​</a></h2><p>不只是&quot;好看&quot;——直线的历史有三个实际好处：</p><ol><li><strong>排查 bug 更快</strong> — 用 <code>git bisect</code> 二分定位 bug 时，线性历史没有分叉干扰，定位更准</li><li><strong>回退更安全</strong> — <code>git revert</code> 按顺序撤销，不会因为跨分叉合并而遗漏改动</li><li><strong>代码 review 更清晰</strong> — PR 里只显示你自己的几个提交，不会被&quot;合并 master 进来的 30 个提交&quot;淹没</li></ol><p>简单说：<strong>merge 告诉我&quot;历史上发生了什么&quot;，rebase 告诉我&quot;这个功能到底改了什么&quot;。</strong></p><blockquote><p>⚠️ <strong>黄金规则：只 rebase 自己本地还没 push 的提交。</strong> Rebase 会重写提交历史。如果 rebase 了已经 push 到远程的提交，同事的仓库和你就会产生冲突，修复起来很头痛。养成习惯：push 之前随意 rebase，push 之后别动。</p></blockquote><h2 id="交互式变基-rebase-i" tabindex="-1">交互式变基：rebase -i <a class="header-anchor" href="#交互式变基-rebase-i" aria-label="Permalink to &quot;交互式变基：rebase -i&quot;">​</a></h2><p><code>rebase -i</code> 让你在变基的同时<strong>编辑提交历史</strong>——合并多个小提交、改提交信息、删除无用提交。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD~3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 整理最近 3 个提交</span></span></code></pre></div><p>Git 会打开编辑器，列出这 3 个提交：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pick a1b2c3d 完成了登录页面</span></span>
<span class="line"><span>pick e4f5a6b 修复了一个小样式问题</span></span>
<span class="line"><span>pick c7d8e9f 调整了按钮颜色</span></span></code></pre></div><p>把 <code>pick</code> 改成其他命令：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>场景</th></tr></thead><tbody><tr><td><code>pick</code></td><td>保留这个提交</td><td>默认</td></tr><tr><td><code>squash</code></td><td>合并到上一个提交，保留提交信息</td><td>把小修复合并进主提交</td></tr><tr><td><code>reword</code></td><td>改提交信息</td><td>提交信息写错了</td></tr><tr><td><code>drop</code></td><td>删除这个提交</td><td>这个提交不需要了</td></tr></tbody></table><p>最常用的是 <code>squash</code>——把&quot;改了一个小问题&quot;&quot;调整颜色&quot;这些小提交合并成一条&quot;完成登录功能&quot;：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pick a1b2c3d 完成了登录页面</span></span>
<span class="line"><span>squash e4f5a6b 修复了一个小样式问题</span></span>
<span class="line"><span>squash c7d8e9f 调整了按钮颜色</span></span></code></pre></div><p>保存退出，三条提交合并成一条，历史干干净净。</p><h2 id="merge-还是-rebase" tabindex="-1">merge 还是 rebase <a class="header-anchor" href="#merge-还是-rebase" aria-label="Permalink to &quot;merge 还是 rebase&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>merge</th><th>rebase</th></tr></thead><tbody><tr><td>历史形态</td><td>保留分支分叉，真实</td><td>一条直线，整洁</td></tr><tr><td>提交记录</td><td>原样保留</td><td>会被重写</td></tr><tr><td>什么时候用</td><td>合并到公共分支（master/develop）</td><td>整理自己的 feature 分支，再合并</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ol><li><strong>rebase = 把提交搬到最新节点之后</strong> — 历史变成一条直线</li><li><strong>rebase -i 能改历史</strong> — squash 合并小提交、reword 改信息、drop 删提交</li><li><strong>merge 保留真实、rebase 保持整洁</strong> — 合并公共分支用 merge，整理自己分支用 rebase</li><li><strong>别 rebase 已 push 的提交</strong> — 只在自己本地玩，推过的别动</li></ol><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>创建两个分支，各做几次提交，用 <code>git rebase</code> 变基后再合并，对比 merge 的历史差异</li><li>做 3 个小提交，用 <code>git rebase -i HEAD~3</code> 把它们 squash 成一条</li><li>用 <code>git reflog</code> 查看 rebase 前后 HEAD 的变化</li><li>思考：如果 rebase 过程中出现冲突该怎么处理？（提示：解决冲突 → <code>git add</code> → <code>git rebase --continue</code>）</li></ol>`,46)])])}const q=a(o,[["render",p]]);export{k as __pageData,q as default};
